package ktanesolver.module.modded.regular.lionsshare;import static org.assertj.core.api.Assertions.assertThat;import java.util.*;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.*;
class LionsShareSolverTest{private final LionsShareSolver s=new LionsShareSolver();@Test void calculatesEveryEntitlementSourceAndLeadRemainder(){BombEntity b=new BombEntity();b.setSerialNumber("M1U2A3");b.setIndicators(Map.of("MOT",true,"FRQ",false));ModuleEntity m=new ModuleEntity();var out=((SolveSuccess<LionsShareOutput>)s.solve(new RoundEntity(),b,m,new LionsShareInput(1,List.of("Mohatu","Uru","Ahadi","Mufasa","Tojo"),"Uru"))).output();assertThat(out.portions()).extracting(LionsShareOutput.Portion::percentage).containsExactly(51,22,18,0,9);assertThat(out.portions()).extracting(LionsShareOutput.Portion::entitlement).containsExactly(17,7,6,0,3);assertThat(out.totalEntitlement()).isEqualTo(33);assertThat(m.getState()).containsEntry("lionsShareYear",1).containsEntry("lionsShareRemovedLions",List.of("Mufasa"));}@Test void validatesTimelineLeadAndUnbornMother(){BombEntity b=new BombEntity();b.setSerialNumber("ABC123");assertThat(s.solve(new RoundEntity(),b,new ModuleEntity(),new LionsShareInput(1,List.of("Mohatu","Mufasa"),"Mufasa"))).isInstanceOf(SolveFailure.class);assertThat(s.solve(new RoundEntity(),b,new ModuleEntity(),new LionsShareInput(1,List.of("Mohatu","Uru"),"Mohatu"))).isInstanceOf(SolveFailure.class);}}
